  if (i < len && input.charCodeAt(i) === 10) i++;

  const seqParts: string[] = [];
  while (i < len && input.charCodeAt(i) !== 62) {
    const lineStart = i;
    while (i < len && input.charCodeAt(i) !== 10 && input.charCodeAt(i) !== 13) i++;
    if (i > lineStart) seqParts.push(input.slice(lineStart, i));

    if (i < len && input.charCodeAt(i) === 13) i++;
    if (i < len && input.charCodeAt(i) === 10) i++;
  }

  const seq = seqParts.join('');
  const revCompChars = new Array(seq.length);
  for (let p = 0, q = seq.length - 1; q >= 0; p++, q--) {
    const ch = seq.charAt(q);
